// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));

        uint256 seedFund = bound(amount, 1, 1 ether);
        vm.deal(address(this), seedFund);
        vm.prank(address(this));
        (bool s,) = address(c).call{value: seedFund}("");
        require(s);

        vm.deal(attacker, 1 ether);

        bool ok;
        vm.prank(attacker);
        try c.withdraw(seedFund) { ok = true; } catch { ok = false; }

        assertTrue(address(c).balance == seedFund);
    }
}
